#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# Secret names must match .env.example, the canonical list (enforced by
# tests/test_secret_names.py).

SAVE_ENV=0

# secret_is_set NAME: does this repo already have that GitHub Actions secret?
secret_is_set() {
  local names
  names=$(gh secret list --json name -q '.[].name' 2>/dev/null) || return 1
  grep -x "$1" >/dev/null <<< "$names"
}

# should_capture NAME: true unless the secret is already set and the human
# wants to keep it, which makes re-runs safe. GitHub secrets can't be read
# back, so a kept secret that's missing from an opted-in .env is captured again.
should_capture() {
  secret_is_set "$1" || return 0
  if (( SAVE_ENV )) && [[ -z "$(_existing "$1" || true)" ]]; then
    note "GitHub secret $1 is set, but missing from $ENV_FILE, so it's needed once more."
    return 0
  fi
  note "GitHub secret $1 is already set."
  confirm "Replace it?"
}

# remember NAME VALUE: also save to the local .env, if the human opted in.
remember() {
  (( SAVE_ENV )) && write_env "$1" "$2"
  return 0
}

# api_status: reads a curl config on stdin (so secrets stay out of `ps`),
# prints the HTTP status code.
api_status() {
  curl -s -o /dev/null -w '%{http_code}' --max-time 15 -K - || true
}

# capture_checked NAME "Prompt" CONFIG: ask for a secret until the API accepts
# it. CONFIG is a curl config with one %s where the value goes.
capture_checked() {
  local name="$1" prompt="$2" config="$3" status
  while true; do
    ask_secret "$name" "$prompt"
    if [[ -z "${!name}" ]]; then warn "Nothing was pasted."; continue; fi
    # shellcheck disable=SC2059
    status=$(printf "$config" "${!name}" | api_status)
    if [[ "$status" == 200 ]]; then note "✓ accepted by the API"; return; fi
    warn "The API rejected that value (HTTP $status)."
    if confirm "Keep it anyway?"; then return; fi
  done
}

# Prints "<id> <name>" for the sender of the newest message in a getUpdates
# response; fails if there is none.
LATEST_SENDER='
import json, sys
updates = json.load(sys.stdin)["result"]
senders = [u["message"]["from"] for u in updates if "from" in u.get("message", {})]
sender = senders[-1]
print(sender["id"], sender.get("first_name", ""), "@" + sender.get("username", "?"))
'

run_wizard() {

TOTAL_STAGES=6
cd "$(dirname "${BASH_SOURCE[0]}")/.."
TELEGRAM_BOT_TOKEN="" TELEGRAM_OWNER_ID="" HIKERAPI_KEY="" GROQ_API_KEY="" DEEPSEEK_API_KEY=""

banner "InstaAutomation setup: Telegram bot and API keys"

stage "Preflight: GitHub CLI and local .env"
say "Every value is stored as a GitHub Actions secret on this repo, using the gh CLI."
if gh auth status >/dev/null 2>&1 && gh repo view >/dev/null 2>&1; then
  note "✓ gh is logged in and can see $(gh repo view --json nameWithOwner -q .nameWithOwner)"
else
  warn "gh isn't logged in, or can't see this repo."
  step "In another terminal, run: gh auth login"
  pause "Press Enter once that's done (or to continue and set the secrets by hand later)."
fi
say ""
say "The values can also go into a local, gitignored $ENV_FILE for adapter smoke tests."
if confirm "Also save them to $ENV_FILE?"; then SAVE_ENV=1; fi

stage "Telegram: create the bot"
if should_capture TELEGRAM_BOT_TOKEN; then
  say "The bot is your inbox: share reels to it, and it reacts ✅ or ❌."
  open_url "https://t.me/BotFather"
  step "In the chat with @BotFather, send /newbot"
  step "Give it a display name (anything, e.g. Reel Inbox)"
  step "Give it a username ending in 'bot' (e.g. my_reel_inbox_bot)"
  step "BotFather replies with an HTTP API token like 123456789:AAH...; copy it"
  capture_checked TELEGRAM_BOT_TOKEN "Paste the bot token:" \
    'url = "https://api.telegram.org/bot%s/getMe"\n'
  remember TELEGRAM_BOT_TOKEN "$TELEGRAM_BOT_TOKEN"
  set_secret TELEGRAM_BOT_TOKEN "$TELEGRAM_BOT_TOKEN"
else
  note "Keeping the existing bot token."
fi
pause

stage "Telegram: find your user ID"
if should_capture TELEGRAM_OWNER_ID; then
  say "The pipeline only accepts reels from you, identified by your numeric Telegram user ID."
  if [[ -z "$TELEGRAM_BOT_TOKEN" ]]; then
    note "Looking up your ID needs the bot token; it's only used for this lookup."
    ask_secret TELEGRAM_BOT_TOKEN "Paste the bot token:"
  fi
  bot_username=$(printf 'url = "https://api.telegram.org/bot%s/getMe"\n' "$TELEGRAM_BOT_TOKEN" \
    | curl -s --max-time 15 -K - \
    | python3 -c 'import json, sys; print(json.load(sys.stdin)["result"]["username"])' 2>/dev/null) || bot_username=""
  [[ -n "$bot_username" ]] && open_url "https://t.me/$bot_username"
  step "Open the chat with your bot${bot_username:+ (@$bot_username)}, press Start, and send it any message"
  pause "Press Enter once you've sent it."
  while true; do
    found=$(printf 'url = "https://api.telegram.org/bot%s/getUpdates"\n' "$TELEGRAM_BOT_TOKEN" \
      | curl -s --max-time 15 -K - | python3 -c "$LATEST_SENDER" 2>/dev/null) || found=""
    if [[ -n "$found" ]]; then
      read -r owner_id owner_label <<< "$found"
      say "The newest message came from: $owner_label (ID $owner_id)"
      if confirm "Is that you?"; then TELEGRAM_OWNER_ID="$owner_id"; break; fi
    else
      warn "No messages found yet."
    fi
    if confirm "Type your ID in by hand instead?"; then
      until [[ "$TELEGRAM_OWNER_ID" =~ ^[0-9]+$ ]]; do
        ask TELEGRAM_OWNER_ID "Your numeric Telegram user ID:"
      done
      break
    fi
    pause "Send the bot another message, then press Enter to check again."
  done
  remember TELEGRAM_OWNER_ID "$TELEGRAM_OWNER_ID"
  set_secret TELEGRAM_OWNER_ID "$TELEGRAM_OWNER_ID"
else
  note "Keeping the existing owner ID."
fi
pause

stage "HikerAPI: reel downloads"
if should_capture HIKERAPI_KEY; then
  say "HikerAPI fetches each reel's video and caption (about \$0.0006 per request)."
  open_url "https://hikerapi.com/registration"
  step "Sign up (or log in)"
  step "Find your API access key in the HikerAPI dashboard and copy it"
  note "The dashboard layout isn't documented; the key is checked against the API below."
  capture_checked HIKERAPI_KEY "Paste the HikerAPI access key:" \
    'url = "https://api.hikerapi.com/sys/balance"\nheader = "x-access-key: %s"\n'
  remember HIKERAPI_KEY "$HIKERAPI_KEY"
  set_secret HIKERAPI_KEY "$HIKERAPI_KEY"
else
  note "Keeping the existing HikerAPI key."
fi
pause

stage "Groq: transcription"
if should_capture GROQ_API_KEY; then
  say "Groq runs Whisper to transcribe each reel's audio."
  open_url "https://console.groq.com/keys"
  step "Log in, click Create API Key, and name it InstaAutomation"
  step "Copy the key now; Groq only shows it once"
  capture_checked GROQ_API_KEY "Paste the Groq API key:" \
    'url = "https://api.groq.com/openai/v1/models"\nheader = "Authorization: Bearer %s"\n'
  remember GROQ_API_KEY "$GROQ_API_KEY"
  set_secret GROQ_API_KEY "$GROQ_API_KEY"
else
  note "Keeping the existing Groq key."
fi
pause

stage "DeepSeek: summarization"
if should_capture DEEPSEEK_API_KEY; then
  say "DeepSeek turns each reel into a knowledge-base entry."
  open_url "https://platform.deepseek.com/api_keys"
  step "Log in, click Create new API key, and name it InstaAutomation"
  step "Copy the key now; DeepSeek only shows it once"
  capture_checked DEEPSEEK_API_KEY "Paste the DeepSeek API key:" \
    'url = "https://api.deepseek.com/models"\nheader = "Authorization: Bearer %s"\n'
  remember DEEPSEEK_API_KEY "$DEEPSEEK_API_KEY"
  set_secret DEEPSEEK_API_KEY "$DEEPSEEK_API_KEY"
  say ""
  say "DeepSeek is prepaid: with a zero balance, summarization fails with 'Insufficient Balance'."
  if confirm "Open the top-up page to add a few dollars?"; then
    open_url "https://platform.deepseek.com/top_up"
  fi
else
  note "Keeping the existing DeepSeek key."
fi
pause

finish
}

run_wizard "$@"; exit
